  (59, 'Arun Das', null, 'IN', 'M', 'PROD', 'OPR', 'W1', 'WRK', 6, 'NOTICE', date '2022-06-16', date '1995-12-06', null, '60076759', '+968 90433709', 'SOHAR', 160, null, 8, 41, 66, null, null, 20, true, 265, 66, 20, 'HSBC Oman', 'BBMEOMRX', '037'),
  (60, 'Jose Santos', null, 'PH', 'M', 'WH', 'DRV', 'W1', 'WRK', 9, 'SEPARATE', date '2014-01-19', date '1976-01-07', null, '60078060', '+968 90441060', 'WH1', 1500, null, 19, 55, 83, 600, 40, 300, false, 189, 47, 20, null, null, null);

create temp table seed_ids(k text primary key, id uuid);

do $seed$
declare
  v jsonb; r record; d record; u record; v_ent uuid; v_id uuid; v_rev uuid; v_doc uuid; i int := 0;
  admin uuid; hrm uuid; hro uuid; fin uuid; boss uuid;
begin
  select id into admin from seed_users where email = 'admin@aact.test';
  select id into hrm   from seed_users where email = 'hr.manager@aact.test';
  select id into hro   from seed_users where email = 'hr.officer@aact.test';
  select id into fin   from seed_users where email = 'finance@aact.test';

  -- roles (through the same API the app uses, so the audit trail is real).
  -- If a real administrator already exists (e.g. the cloud test project), that administrator grants the demo roles.
  select ur.user_id into boss from hr.user_roles ur
   where ur.role_code = 'SUPER_ADMIN' and ur.revoked_at is null and ur.user_id not in (select id from seed_users)
   order by ur.granted_at limit 1;
  if boss is null then
    perform set_config('request.jwt.claim.sub', admin::text, false);
    perform public.hr_claim_first_admin();
    boss := admin;
  end if;
  perform set_config('request.jwt.claim.sub', boss::text, false);
  for u in select * from seed_users where id <> boss loop
    perform public.hr_set_user_roles(u.id, u.roles);
  end loop;

  -- organisation (HR manager)
  perform set_config('request.jwt.claim.sub', hrm::text, false);
  v := public.hr_save_master('entity', '{"code":"AACT","name_en":"AACT Industries LLC (DEMO)","name_ar":"شركة أ.أ.س.ت للصناعات (تجريبي)","cr_number":"0000000"}');
  v_ent := (v->>'id')::uuid;
  insert into seed_ids values ('loc:SOHAR', (public.hr_save_master('location', jsonb_build_object('entity_id', v_ent, 'code', 'SOHAR', 'name_en', 'Sohar factory', 'name_ar', 'مصنع صحار', 'location_type', 'FACTORY'))->>'id')::uuid);
  insert into seed_ids values ('loc:MCT', (public.hr_save_master('location', jsonb_build_object('entity_id', v_ent, 'code', 'MCT', 'name_en', 'Muscat head office', 'name_ar', 'المكتب الرئيسي - مسقط', 'location_type', 'OFFICE'))->>'id')::uuid);
  insert into seed_ids values ('loc:WH1', (public.hr_save_master('location', jsonb_build_object('entity_id', v_ent, 'code', 'WH1', 'name_en', 'Sohar warehouse', 'name_ar', 'مستودع صحار', 'location_type', 'WAREHOUSE'))->>'id')::uuid);
  insert into seed_ids values ('cc:CC100', (public.hr_save_master('cost_centre', jsonb_build_object('entity_id', v_ent, 'code', 'CC100', 'name_en', 'Production', 'name_ar', 'الإنتاج'))->>'id')::uuid);
  insert into seed_ids values ('cc:CC200', (public.hr_save_master('cost_centre', jsonb_build_object('entity_id', v_ent, 'code', 'CC200', 'name_en', 'Administration', 'name_ar', 'الإدارة'))->>'id')::uuid);
  insert into seed_ids values ('cc:CC300', (public.hr_save_master('cost_centre', jsonb_build_object('entity_id', v_ent, 'code', 'CC300', 'name_en', 'Maintenance', 'name_ar', 'الصيانة'))->>'id')::uuid);
  insert into seed_ids values ('cc:CC400', (public.hr_save_master('cost_centre', jsonb_build_object('entity_id', v_ent, 'code', 'CC400', 'name_en', 'Sales and marketing', 'name_ar', 'المبيعات والتسويق'))->>'id')::uuid);
  insert into seed_ids values ('cc:CC500', (public.hr_save_master('cost_centre', jsonb_build_object('entity_id', v_ent, 'code', 'CC500', 'name_en', 'Warehouse and logistics', 'name_ar', 'المستودعات والخدمات اللوجستية'))->>'id')::uuid);
  insert into seed_ids values ('dep:OPS', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'OPS', 'name_en', 'Operations', 'name_ar', 'العمليات', 'parent_id', null, 'cost_centre_id', (select id from seed_ids where k = 'cc:CC100')))->>'id')::uuid);
  insert into seed_ids values ('dep:PROD', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'PROD', 'name_en', 'Production', 'name_ar', 'الإنتاج', 'parent_id', (select id from seed_ids where k = 'dep:OPS'), 'cost_centre_id', (select id from seed_ids where k = 'cc:CC100')))->>'id')::uuid);
  insert into seed_ids values ('dep:MAINT', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'MAINT', 'name_en', 'Maintenance', 'name_ar', 'الصيانة', 'parent_id', (select id from seed_ids where k = 'dep:OPS'), 'cost_centre_id', (select id from seed_ids where k = 'cc:CC300')))->>'id')::uuid);
  insert into seed_ids values ('dep:QC', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'QC', 'name_en', 'Quality control', 'name_ar', 'مراقبة الجودة', 'parent_id', (select id from seed_ids where k = 'dep:OPS'), 'cost_centre_id', (select id from seed_ids where k = 'cc:CC100')))->>'id')::uuid);
  insert into seed_ids values ('dep:WH', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'WH', 'name_en', 'Warehouse and logistics', 'name_ar', 'المستودعات والخدمات اللوجستية', 'parent_id', (select id from seed_ids where k = 'dep:OPS'), 'cost_centre_id', (select id from seed_ids where k = 'cc:CC500')))->>'id')::uuid);
  insert into seed_ids values ('dep:HR', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'HR', 'name_en', 'Human resources', 'name_ar', 'الموارد البشرية', 'parent_id', null, 'cost_centre_id', (select id from seed_ids where k = 'cc:CC200')))->>'id')::uuid);
  insert into seed_ids values ('dep:FIN', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'FIN', 'name_en', 'Finance', 'name_ar', 'المالية', 'parent_id', null, 'cost_centre_id', (select id from seed_ids where k = 'cc:CC200')))->>'id')::uuid);
  insert into seed_ids values ('dep:SALES', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'SALES', 'name_en', 'Sales', 'name_ar', 'المبيعات', 'parent_id', null, 'cost_centre_id', (select id from seed_ids where k = 'cc:CC400')))->>'id')::uuid);
  insert into seed_ids values ('dep:ADMIN', (public.hr_save_master('department', jsonb_build_object('entity_id', v_ent, 'code', 'ADMIN', 'name_en', 'Administration', 'name_ar', 'الشؤون الإدارية', 'parent_id', null, 'cost_centre_id', (select id from seed_ids where k = 'cc:CC200')))->>'id')::uuid);
  insert into seed_ids values ('gr:W1', (public.hr_save_master('grade', jsonb_build_object('entity_id', v_ent, 'code', 'W1', 'name_en', 'Worker I', 'level', 1, 'min_basic', 150, 'max_basic', 300))->>'id')::uuid);
  insert into seed_ids values ('gr:W2', (public.hr_save_master('grade', jsonb_build_object('entity_id', v_ent, 'code', 'W2', 'name_en', 'Worker II', 'level', 2, 'min_basic', 250, 'max_basic', 450))->>'id')::uuid);
  insert into seed_ids values ('gr:S1', (public.hr_save_master('grade', jsonb_build_object('entity_id', v_ent, 'code', 'S1', 'name_en', 'Staff I', 'level', 3, 'min_basic', 400, 'max_basic', 900))->>'id')::uuid);
  insert into seed_ids values ('gr:S2', (public.hr_save_master('grade', jsonb_build_object('entity_id', v_ent, 'code', 'S2', 'name_en', 'Supervisor', 'level', 4, 'min_basic', 700, 'max_basic', 1300))->>'id')::uuid);
  insert into seed_ids values ('gr:M1', (public.hr_save_master('grade', jsonb_build_object('entity_id', v_ent, 'code', 'M1', 'name_en', 'Manager I', 'level', 5, 'min_basic', 1200, 'max_basic', 2500))->>'id')::uuid);
  insert into seed_ids values ('gr:M2', (public.hr_save_master('grade', jsonb_build_object('entity_id', v_ent, 'code', 'M2', 'name_en', 'Manager II', 'level', 6, 'min_basic', 2000, 'max_basic', 3500))->>'id')::uuid);
  insert into seed_ids values ('job:OPSMGR', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'OPSMGR', 'name_en', 'Operations manager', 'name_ar', 'مدير العمليات'))->>'id')::uuid);
  insert into seed_ids values ('job:HRMGR', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'HRMGR', 'name_en', 'HR manager', 'name_ar', 'مدير الموارد البشرية'))->>'id')::uuid);
  insert into seed_ids values ('job:FINMGR', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'FINMGR', 'name_en', 'Finance manager', 'name_ar', 'مدير المالية'))->>'id')::uuid);
  insert into seed_ids values ('job:SLSMGR', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'SLSMGR', 'name_en', 'Sales manager', 'name_ar', 'مدير المبيعات'))->>'id')::uuid);
  insert into seed_ids values ('job:PSUP', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'PSUP', 'name_en', 'Production supervisor', 'name_ar', 'مشرف الإنتاج'))->>'id')::uuid);
  insert into seed_ids values ('job:MENG', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'MENG', 'name_en', 'Maintenance engineer', 'name_ar', 'مهندس صيانة'))->>'id')::uuid);
  insert into seed_ids values ('job:QCSUP', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'QCSUP', 'name_en', 'Quality control supervisor', 'name_ar', 'مشرف مراقبة الجودة'))->>'id')::uuid);
  insert into seed_ids values ('job:STK', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'STK', 'name_en', 'Storekeeper', 'name_ar', 'أمين مخزن'))->>'id')::uuid);
  insert into seed_ids values ('job:HRO', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'HRO', 'name_en', 'HR officer', 'name_ar', 'أخصائي موارد بشرية', 'omani_only', true, 'omani_only_source', 'DUMMY DATA - replace with the applicable Ministerial decision'))->>'id')::uuid);
  insert into seed_ids values ('job:ACC', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'ACC', 'name_en', 'Accountant', 'name_ar', 'محاسب'))->>'id')::uuid);
  insert into seed_ids values ('job:SLSE', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'SLSE', 'name_en', 'Sales executive', 'name_ar', 'مندوب مبيعات'))->>'id')::uuid);
  insert into seed_ids values ('job:ADM', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'ADM', 'name_en', 'Administrative assistant', 'name_ar', 'مساعد إداري'))->>'id')::uuid);
  insert into seed_ids values ('job:OPR', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'OPR', 'name_en', 'Machine operator', 'name_ar', 'مشغل آلة'))->>'id')::uuid);
  insert into seed_ids values ('job:HLP', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'HLP', 'name_en', 'Production helper', 'name_ar', 'عامل إنتاج'))->>'id')::uuid);
  insert into seed_ids values ('job:MTECH', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'MTECH', 'name_en', 'Maintenance technician', 'name_ar', 'فني صيانة'))->>'id')::uuid);
  insert into seed_ids values ('job:QCI', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'QCI', 'name_en', 'Quality inspector', 'name_ar', 'مفتش جودة'))->>'id')::uuid);
  insert into seed_ids values ('job:FLD', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'FLD', 'name_en', 'Forklift operator', 'name_ar', 'مشغل رافعة شوكية'))->>'id')::uuid);
  insert into seed_ids values ('job:DRV', (public.hr_save_master('job_title', jsonb_build_object('entity_id', v_ent, 'code', 'DRV', 'name_en', 'Driver', 'name_ar', 'سائق'))->>'id')::uuid);
  insert into seed_ids values ('cat:STAFF', (public.hr_save_master('category', jsonb_build_object('entity_id', v_ent, 'code', 'STAFF', 'name_en', 'Monthly staff', 'name_ar', 'موظفون شهريون', 'counts_for_omanisation', true))->>'id')::uuid);
  insert into seed_ids values ('cat:WRK', (public.hr_save_master('category', jsonb_build_object('entity_id', v_ent, 'code', 'WRK', 'name_en', 'Workers', 'name_ar', 'العمال', 'counts_for_omanisation', true))->>'id')::uuid);
  insert into seed_ids values ('cat:TRN', (public.hr_save_master('category', jsonb_build_object('entity_id', v_ent, 'code', 'TRN', 'name_en', 'Trainees (not counted)', 'name_ar', 'متدربون (غير محتسبين)', 'counts_for_omanisation', false))->>'id')::uuid);

  -- employees (HR officer), managers first
  perform set_config('request.jwt.claim.sub', hro::text, false);
  for r in select * from seed_people order by no loop
    v := public.hr_save_employee(jsonb_strip_nulls(jsonb_build_object(
      'entity_id', v_ent, 'full_name_en', r.name_en, 'full_name_ar', r.name_ar, 'nationality', r.nat, 'gender', r.gender,
      'date_of_birth', r.dob::text, 'join_date', r.join_date::text, 'civil_number', r.civil, 'work_email', r.email,
      'mobile', r.mobile, 'marital_status', case when r.no % 3 = 0 then 'SINGLE' else 'MARRIED' end,
      'probation_end_date', case when r.special like '%PROBATION%' then (r.join_date + 90)::text end,
      'assignment', jsonb_strip_nulls(jsonb_build_object(
        'department_id', (select id from seed_ids where k = 'dep:' || r.dept),
        'job_title_id',  (select id from seed_ids where k = 'job:' || r.job),
        'grade_id',      (select id from seed_ids where k = 'gr:' || r.grade),
        'category_id',   (select id from seed_ids where k = 'cat:' || r.cat),
        'location_id',   (select id from seed_ids where k = 'loc:' || r.loc),
        'manager_id',    (select emp_id from seed_people m where m.no = r.mgr),
        'employment_type', case when r.cat = 'TRN' then 'TRAINEE' else 'FULL_TIME' end)))));
    update seed_people set emp_id = (v->'employee'->>'id')::uuid where no = r.no;
  end loop;

  -- contracts
  for r in select * from seed_people order by no loop
    if r.nat = 'OM' then
      perform public.hr_save_contract(r.emp_id, jsonb_build_object('contract_type', 'INDEFINITE', 'start_date', r.join_date::text,
              'probation_days', 90, 'notice_days', case when r.grade like 'M%' then 90 else 30 end));
    else
      perform public.hr_save_contract(r.emp_id, jsonb_build_object('contract_type', 'FIXED_TERM',
              'start_date', greatest(r.join_date, current_date + r.contract_off - 730)::text,
              'end_date', (current_date + r.contract_off)::text, 'probation_days', 90, 'notice_days', 30));
    end if;
  end loop;

  -- documents (metadata only; no files are attached in dummy data)
  for r in select * from seed_people order by no loop
    v := public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'PASSPORT', 'doc_number', 'DP' || lpad((r.no * 48271 % 9000000 + 1000000)::text, 7, '0'),
           'issue_date', (current_date + r.pass_off - 3650)::text, 'expiry_date', (current_date + r.pass_off)::text,
           'issuing_authority', 'Passport office (dummy)'));
    if r.no % 3 <> 0 then insert into seed_ids values ('verify:' || r.no, (v->>'id')::uuid); end if;
    if r.cid_off is not null then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'CIVIL_ID', 'doc_number', r.civil,
              'expiry_date', (current_date + r.cid_off)::text, 'issuing_authority', 'Royal Oman Police (dummy)'));
    end if;
    if r.rc_off is not null then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'RESIDENT_CARD', 'doc_number', r.civil,
              'expiry_date', (current_date + r.rc_off)::text, 'issuing_authority', 'Royal Oman Police (dummy)'));
    end if;
    if r.visa_off is not null then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'EMPLOYMENT_VISA', 'doc_number', 'EV' || (r.no * 7919),
              'expiry_date', (current_date + r.visa_off)::text));
    end if;
    if r.wp_off is not null then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'WORK_PERMIT', 'doc_number', 'WP' || (r.no * 104729),
              'expiry_date', (current_date + r.wp_off)::text, 'issuing_authority', 'Ministry of Labour (dummy)'));
    end if;
    if r.med_off is not null then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'MEDICAL_FITNESS', 'doc_number', 'MF' || r.no,
              'expiry_date', (current_date + r.med_off)::text));
    end if;
    if r.lic_off is not null then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'DRIVING_LICENCE', 'doc_number', 'DL' || r.civil,
              'expiry_date', (current_date + r.lic_off)::text, 'issuing_authority', 'Royal Oman Police (dummy)'));
    end if;
    if r.contract_doc then
      perform public.hr_save_document(r.emp_id, jsonb_build_object('doc_type', 'CONTRACT_COPY', 'doc_number', 'C-' || r.no));
    end if;
  end loop;

  -- salary proposals (HR officer) → approvals (HR manager); a few left pending
  for r in select * from seed_people order by no loop
    v := public.hr_propose_compensation(r.emp_id, jsonb_build_object('effective_from', r.join_date::text, 'reason', 'JOIN',
           'lines', jsonb_build_array(jsonb_build_object('component_code', 'BASIC', 'amount', r.basic::text),
                                      jsonb_build_object('component_code', 'HOUSING', 'amount', r.housing::text),
                                      jsonb_build_object('component_code', 'TRANSPORT', 'amount', r.transport::text))));
    if r.special not like '%PENDING_SALARY%' then
      insert into seed_ids values ('rev:' || r.no, (v->>'revision_id')::uuid);
    end if;
  end loop;
  perform set_config('request.jwt.claim.sub', hrm::text, false);
  for d in select id from seed_ids where k like 'rev:%' loop
    perform public.hr_decide_compensation(d.id, true, 'Approved per offer letter (dummy)');
  end loop;
  perform set_config('request.jwt.claim.sub', hro::text, false);
  for r in select * from seed_people where special like '%PENDING_INCREMENT%' loop
    perform public.hr_propose_compensation(r.emp_id, jsonb_build_object('effective_from', (date_trunc('month', current_date) + interval '1 month')::date::text,
            'reason', 'INCREMENT', 'lines', jsonb_build_array(
              jsonb_build_object('component_code', 'BASIC', 'amount', (r.basic + 50)::text),
              jsonb_build_object('component_code', 'HOUSING', 'amount', r.housing::text),
              jsonb_build_object('component_code', 'TRANSPORT', 'amount', r.transport::text))));
  end loop;

  -- bank accounts (HR officer requests → Finance approves); one left pending
  for r in select * from seed_people where bank is not null order by no loop
    v := public.hr_request_bank_change(r.emp_id, jsonb_build_object('bank_name', r.bank, 'account_name', r.name_en,
           'account_number', lpad((r.no * 9176543 % 10000000000000)::text, 16, '0'),
           'iban', 'OM' || lpad((r.no % 90 + 10)::text, 2, '0') || r.bank_code || lpad((r.no * 9176543 % 10000000000000)::text, 16, '0'),
           'swift_code', r.swift));
    if r.special not like '%PENDING_BANK%' then insert into seed_ids values ('bank:' || r.no, (v->'pending'->>'id')::uuid); end if;
  end loop;
  perform set_config('request.jwt.claim.sub', fin::text, false);
  for d in select id from seed_ids where k like 'bank:%' loop
    perform public.hr_decide_bank(d.id, true, 'Checked bank letter (dummy)');
  end loop;

  -- document verification by a second person (HR manager)
  perform set_config('request.jwt.claim.sub', hrm::text, false);
  for d in select id from seed_ids where k like 'verify:%' loop
    perform public.hr_verify_document(d.id);
  end loop;

  -- Omanisation target: proposed by HR officer, approved by HR manager — DUMMY percentage
  perform set_config('request.jwt.claim.sub', hro::text, false);
  v := public.hr_propose_omanisation_target(jsonb_build_object('entity_id', v_ent, 'scope_type', 'ENTITY', 'target_pct', 40,
         'effective_from', date_trunc('year', current_date)::date::text, 'rule_basis', 'COMPANY_POLICY',
         'source_reference', 'DUMMY DATA - replace with the applicable Ministry decision before go-live'));
  v_id := (select (x->>'id')::uuid from jsonb_array_elements(v) x where x->>'status' = 'PENDING' limit 1);
  perform set_config('request.jwt.claim.sub', hrm::text, false);
  perform public.hr_decide_omanisation_target(v_id, true, 'Dummy target for testing');

  -- lifecycle examples
  perform set_config('request.jwt.claim.sub', hro::text, false);
  for r in select * from seed_people where special = 'NOTICE' loop
    perform public.hr_change_status(r.emp_id, jsonb_build_object('action', 'NOTICE', 'date', current_date::text,
            'last_working_date', (current_date + 30)::text, 'separation_type', 'RESIGNATION'));
  end loop;
  for r in select * from seed_people where special = 'SEPARATE' loop
    perform public.hr_change_status(r.emp_id, jsonb_build_object('action', 'SEPARATE', 'date', current_date::text,
            'separation_type', 'END_OF_CONTRACT'));
  end loop;

  -- link demo logins to their employee records
  perform set_config('request.jwt.claim.sub', boss::text, false);
  for u in select su.id, sp.emp_id from seed_users su join seed_people sp on sp.no = su.emp_no loop
    perform public.hr_link_user_employee(u.id, u.emp_id);
  end loop;

  -- reminders
  perform set_config('request.jwt.claim.sub', hrm::text, false);
  perform public.hr_run_expiry_scan();

  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'AACT HRMS dummy data loaded: % employees.', (select count(*) from seed_people);
end
$seed$;

drop table seed_ids;
drop table seed_people;
drop table seed_users;
